const response = $input.first().json;
if (response.statusCode !== 200 || !Array.isArray(response.body)) {
  throw new Error("A lista de execuções FARMA está indisponível.");
}
const attention = new Set(["falhou", "parcial", "revisao_necessaria", "aguardando"]);
const uuid = /^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i;
const known = new Set(["RESPOSTA_INCERTA", "FONTE_ESSENCIAL_INCOMPLETA",
  "REDE_SIMULADA", "AUTENTICACAO_SIMULADA", "FALHA_INTERNA"]);
const rows = response.body
  .filter((item) => item && item.segmento === "FARMA" && typeof item.id === "string" &&
    uuid.test(item.id) && attention.has(item.estado))
  .slice(0, 10);
if (!rows.length) return [{ json: { resultado: "Sem execuções que exigem atenção na amostra.", segmento: "FARMA" } }];
return rows.map((item) => ({ json: {
  id: item.id, estado: item.estado,
  codigo: known.has(item.erro) ? item.erro : item.erro ? "OUTRO_ERRO" : null,
  tentativa: Number.isSafeInteger(item.tentativa) ? item.tentativa : null,
  reserva: Array.isArray(item.resultado?.pendencias) && item.resultado.pendencias.some((p) => p?.motivo === "RESERVA_FARMA"),
  anuncios_parciais: Array.isArray(item.resultado?.pendencias) &&
    item.resultado.pendencias.some((p) => p?.fonte === "anuncios" && p.motivo === "COBERTURA_PARCIAL"),
} }));

const selected = $("Selecionar casos para investigar").all();
const responses = $input.all();
if (selected.length !== responses.length) {
  throw new Error("A conferência das etapas retornou uma quantidade inesperada.");
}
const stageNames = {
  atualizacao_weni: "Atualização Weni", analytics: "Analytics",
  publicacao: "Publicação PostgreSQL", recompra: "Recompra",
  analytics_final: "Analytics após Recompra",
};
return responses.map(({ json: response }, i) => {
  const task = selected[i].json;
  const stages = response.statusCode === 200 && response.body?.estado === task.estado &&
    Array.isArray(response.body.etapas) ? response.body.etapas : [];
  const confirmed = stages.filter((entry) => entry?.estado === "concluida" &&
    Object.hasOwn(stageNames, entry.etapa));
  const last = confirmed.at(-1);
  const next = stages.find((entry) => entry?.estado !== "concluida" &&
    Object.hasOwn(stageNames, entry.etapa));
  let verificacao = "Investigar a etapa e conferir os registros da fonte antes de repetir.";
  if (task.codigo === "RESPOSTA_INCERTA") {
    verificacao = "Conferir a revisão e o recibo da publicação antes de qualquer repetição.";
  } else if (task.codigo === "FONTE_ESSENCIAL_INCOMPLETA") {
    verificacao = "Conferir a cobertura da fonte do Analytics antes de publicar.";
  } else if (task.estado === "aguardando") {
    verificacao = "Acompanhar a próxima tentativa do worker e conferir o checkpoint.";
  } else if (task.reserva && task.anuncios_parciais) {
    verificacao = "Conferir a reserva FARMA e a cobertura de Anúncios na próxima carga.";
  } else if (task.reserva) {
    verificacao = "Conferir a retirada adiada do grupo Opt-Out LGPD na próxima carga.";
  } else if (task.anuncios_parciais) {
    verificacao = "Conferir a cobertura de Anúncios na próxima coleta.";
  }
  return { json: {
    segmento: "FARMA", ambiente: "homologacao", execucao: task.id, estado: task.estado,
    codigo: task.codigo, tentativa: task.tentativa,
    ultima_etapa_confirmada: last ? stageNames[last.etapa] : null,
    primeira_etapa_aberta: next ? stageNames[next.etapa] : null,
    evidencia_etapas: stages.length ? "conferida" : "indisponivel",
    proxima_verificacao: verificacao,
  } };
});
